"import os
import sys

root_dir = "/Users/pranit405/.gemini/antigravity/scratch/audit-it"
js_files = []
for dirpath, _, filenames in os.walk(root_dir):
    for f in filenames:
        if f.endswith(".js"):
            js_files.append(os.path.join(dirpath, f))

print(f"Found {len(js_files)} JS files to verify:")

errors = []
for path in sorted(js_files):
    rel = os.path.relpath(path, root_dir)
    with open(path, "r", encoding="utf-8") as file:
        content = file.read()

    # Check imports exist
    import_lines = [l for l in content.splitlines() if l.strip().startswith("import ")]
    for il in import_lines:
        if " from " in il:
            target_rel = il.split(" from ")[-1].strip().strip(";").strip("\"\'")
            if target_rel.startswith("./") or target_rel.startswith("../"):
                target_path = os.path.normpath(os.path.join(os.path.dirname(path), target_rel))
                if not os.path.exists(target_path):
                    errors.append(f"{rel}: Imported file not found: {target_rel} -> {target_path}")

    print(f"  ✓ {rel} - imports verified")

if errors:
    print("\nERRORS DETECTED:")
    for e in errors:
        print("  ❌", e)
    sys.exit(1)
else:
    print("\nAll JS files passed import path verification successfully!")
"

