import re

pat = re.compile(r"(?:CGST|Central GST)[\s@%]*([0-9\.]+)?%?[\s:]*[₹\s]*([0-9,]+(?:\.[0-9]{2})?)", re.I)

def parse_val(text):
    m = pat.search(text)
    if not m:
        return 0
    g1 = m.group(1)
    g2 = m.group(2)
    if "%" in text:
        return float(g2.replace(",", "")) if g2 else 0.0
    if g1 and g2:
        if g2 in ["0", "00"]:
            return float((g1 + g2).replace(",", ""))
        return float(g2.replace(",", "")) if float(g2.replace(",", "")) > 0 else float(g1.replace(",", ""))
    if g2:
        return float(g2.replace(",", ""))
    if g1:
        return float(g1.replace(",", ""))
    return 0.0

