"/**
 * Strict tax extraction helper:
 * Group 1: optional tax percentage (e.g. 9 or 9.0)
 * Group 2: tax amount (e.g. 990.00 or 1,624.95)
 */
function extractTaxAmountFromMatch(match, line) {
  if (!match) return 0;
  if (line.includes("%")) {
    return match[2] ? parseIndianCurrency(match[2]) : 0;
  }
  if (match[1] && match[2]) {
    if (match[2] === "0" || match[2] === "00") {
      return parseIndianCurrency(match[1] + match[2]);
    }
    const val2 = parseIndianCurrency(match[2]);
    if (val2 > 0) return val2;
    return parseIndianCurrency(match[1] + match[2]);
  }
  if (match[2]) return parseIndianCurrency(match[2]);
  if (match[1]) return parseIndianCurrency(match[1]);
  return 0;
}

/**
 * Checks if raw text contains commercial invoice keywords
 */"

