  const digitalTurnover = (annualTurnover * digitalShare) / 100;
  const cashTurnover = annualTurnover - digitalTurnover;
  const deemedProfit = 
    (digitalTurnover * (digitalRate / 100)) + 
    (cashTurnover * (cashRate / 100));

