"function setupHandlers(container, props) {
  const { 
    state, 
    onUpdateState, 
    verifiedInvoice,
    calcMode,
    annualTurnover,
    digitalShare,
    digitalRate,
    cashRate,
    operatingExpenses,
    cgst,
    sgst,
    igst,
    totalITC 
  } = props;

  if (!onUpdateState) return;

  const btnYes = container.querySelector("#btn-toggle-business-yes");
  const btnNo = container.querySelector("#btn-toggle-business-no");
  if (btnYes) {
    btnYes.addEventListener("click", () => onUpdateState({ isBusinessExpense: true }));
  }
  if (btnNo) {
    btnNo.addEventListener("click", () => onUpdateState({ isBusinessExpense: false }));
  }

  const btn44ad = container.querySelector("#btn-scheme-44ad");
  const btnRegular = container.querySelector("#btn-scheme-regular");
  if (btn44ad) {
    btn44ad.addEventListener("click", () => onUpdateState({ calcMode: '44AD' }));
  }
